"""Algorithm 2 — Subword complexity of the peak word via the level statistic.

The factor of length L read at position m depends on m only through the point
x_m = {(m+1) * alpha} of the circle R/Z, through the identity

    S(m+j) - S(m) = floor(x_m + j*alpha),   0 <= j <= L.

Consequently the integer

    level(L, m) = sum_{j=0}^{L} ( S(m+j) - S(m) - floor(j*alpha) )
                = #{ 1 <= j <= L : {j*alpha} > 1 - x_m }

takes values in {0, ..., L}, is monotone in x_m, and *determines the factor*.
Therefore the subword complexity p(L) equals the number of distinct levels,
which equals the number of arcs of the circle -- cut by the L thresholds
1 - {j*alpha} -- that contain at least one orbit point x_m.

Two implementations are given: an O(N*L) direct count of distinct factors
(used as a cross-check) and an O((L + N) log(L + N)) geometric count using the
arc decomposition, which never materialises a single factor.
"""

from __future__ import annotations

from decimal import Decimal, getcontext
from fractions import Fraction
from math import gcd
from typing import Dict, List, Sequence, Tuple, Union

getcontext().prec = 100

Real = Union[Fraction, Decimal]


def floor_real(x: Real) -> int:
    if isinstance(x, Fraction):
        return x.numerator // x.denominator
    return int(x // 1)


def fract(x: Real) -> Real:
    return x - floor_real(x)


def staircase(alpha: Real, n: int) -> int:
    return floor_real(alpha * (n + 1))


def increment_word(alpha: Real, length: int) -> List[int]:
    s = [staircase(alpha, n) for n in range(length + 1)]
    return [s[n + 1] - s[n] for n in range(length)]


def level(alpha: Real, L: int, m: int) -> int:
    """The level statistic of position m for windows of length L."""
    base = staircase(alpha, m)
    return sum((staircase(alpha, m + j) - base) - floor_real(alpha * j)
               for j in range(L + 1))


def complexity_by_levels(alpha: Real, L: int, horizon: int) -> int:
    """p(L) as the number of distinct levels seen over `horizon` positions."""
    return len({level(alpha, L, m) for m in range(horizon)})


def complexity_direct(word: Sequence[int], L: int) -> int:
    """p(L) by collecting distinct factors (cross-check, O(N*L))."""
    return len({tuple(word[m:m + L]) for m in range(len(word) - L + 1)})


def complexity_geometric(alpha: Real, L: int, horizon: int) -> int:
    """p(L) by counting occupied arcs of the circle.

    The L thresholds 1 - {j*alpha}, j = 1..L, cut the circle into at most
    L+1 arcs; the level of a position is the index of the arc containing
    x_m = {(m+1)*alpha}.  Counting occupied arcs avoids building any factor.
    """
    thresholds = sorted(1 - fract(alpha * j) for j in range(1, L + 1))
    occupied = set()
    for m in range(horizon):
        x = fract(alpha * (m + 1))
        lo, hi = 0, len(thresholds)
        while lo < hi:                      # arc index = # thresholds <= x
            mid = (lo + hi) // 2
            if thresholds[mid] <= x:
                lo = mid + 1
            else:
                hi = mid
        occupied.add(lo)
    return len(occupied)


def complexity_profile_rational(P: int, Q: int, max_len: int) -> List[int]:
    """Theoretical profile min(L+1, P+Q) for coprime P, Q (checked against data)."""
    if gcd(P, Q) != 1:
        raise ValueError("P and Q must be coprime for the closed formula")
    return [min(L + 1, P + Q) for L in range(1, max_len + 1)]


def audit(alpha: Real, max_len: int, horizon: int) -> Dict[int, Tuple[int, int, int]]:
    """For L = 1..max_len return (direct, by levels, geometric) counts."""
    word = increment_word(alpha, horizon + max_len + 1)
    out: Dict[int, Tuple[int, int, int]] = {}
    for L in range(1, max_len + 1):
        out[L] = (complexity_direct(word, L),
                  complexity_by_levels(alpha, L, horizon),
                  complexity_geometric(alpha, L, horizon))
    return out


if __name__ == "__main__":
    print("Irrational slope alpha = 2 - sqrt(2)  (theory: p(L) = L + 1)")
    a = Decimal(2) - Decimal(2).sqrt()
    for L, triple in audit(a, 10, 4000).items():
        print(f"  L = {L:2}: direct={triple[0]:3}  levels={triple[1]:3}  "
              f"geometric={triple[2]:3}   theory={L + 1}")

    print("\nRational slope alpha = 3/8, P=3, Q=5 (theory: p(L) = min(L+1, 8))")
    b = Fraction(3, 8)
    theory = complexity_profile_rational(3, 5, 12)
    for L, triple in audit(b, 12, 2000).items():
        print(f"  L = {L:2}: direct={triple[0]:3}  levels={triple[1]:3}  "
              f"geometric={triple[2]:3}   theory={theory[L - 1]}")
